window.MG_LAZY_DATA["data/lazy/resources/comm-v28-081-3649e39dff1be4ec.json"]={sha256:"3649e39dff1be4ece8687681578e779d00e59ed59559dcf7ce234e3c57dd1da7",value:{"sources":[{"id":"v28-case-b12237ac3fc60f0b","url":"https://www.etsi.org/deliver/etsi_ts/145000_145099/145002/15.02.00_60/ts_145002v150200p.pdf","title":"ETSI TS 145 002 V15.2.0: GSM/EDGE Multiplexing and multiple access","titleEn":"ETSI TS 145 002 V15.2.0: GSM/EDGE Multiplexing and multiple access","publisher":"ETSI / 3GPP","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"comm-v28-081","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"comm-v28-081","related":[{"id":"comm-v28-082","referenceUrls":["https://www.etsi.org/deliver/etsi_ts/145000_145099/145002/15.02.00_60/ts_145002v150200p.pdf"],"title":"GPRS 多時槽：上下行資源守恆","titleEn":"GPRS multislot: uplink/downlink resource conservation","why":"用兩課的可觀察驗收條件比較模型邊界：交付物能重現 4560 microsecond/frame 與 4320 microsecond/frame，保留失敗情境且每個通過判定有明確門檻；需分開列出模型未涵蓋的實際系統驗證。","whyEn":"Compare model boundaries using observable acceptance criteria: The artifacts must reproduce 4560 microsecond/frame and 4320 microsecond/frame, preserve failing scenarios and attach a threshold to each pass decision; list actual-system validation outside this model separately.","difference":"能推導並解釋48 kbit/s與36 kbit/s，建立gprs_slot_map.csv、能力假設、淨位元帳本，並完成以下驗收：需求40 kbit/s時只有4槽名義配置足夠；若能力或轉向限制禁止該配置，必須重設需求。","differenceEn":"Derive and explain 48 kbit/s and 36 kbit/s; create gprs_slot_map.csv, capability assumptions and useful-bit ledger; apply this acceptance decision: Only four slots meet a40 kbit/s nominal target; revise the demand if capability or turnaround constraints forbid that assignment.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["從原理 TDMA以互不重疊的時槽分配共用媒介；資料時間須扣保護時間，時槽數與語音淨位元率不可直接等同。 展開基準式 8*(600-30)；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：列8個槽的起訖與資料區，總框長4800 microsecond不變；確認無資料跨越保護邊界。 將兩條推導一起存入 tdma_slots.csv、到達偏移表、保護時間驗收。","從原理 分配給封包的時槽受終端能力與方向切換約束；單槽有效率乘槽數只是固定條件模型。 展開基準式 12*4；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：建立8槽配置圖並標UL/DL/空閒，逐筆累加淨資料；不將編碼前符元率當12 kbit/s。 將兩條推導一起存入 gprs_slot_map.csv、能力假設、淨位元帳本。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Starting from TDMA divides a shared medium into nonoverlapping slots; guard time reduces data time and slot count is not a voice payload rate., expand baseline expression 8*(600-30); record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: List start/end/data intervals for eight slots; total frame duration remains4800 microseconds and no data crosses a guard boundary. Save both derivations with tdma_slots.csv, arrival offsets and guard-time acceptance.","Starting from Packet timeslots are constrained by terminal capability and direction switching; per-slot goodput times slot count is only a fixed-condition model., expand baseline expression 12*4; record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: Draw eight slots labeled UL/DL/idle and sum useful bits; do not confuse the12 kbit/s assumption with uncoded symbol rate. Save both derivations with gprs_slot_map.csv, capability assumptions and useful-bit ledger.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"comm-v28-091","referenceUrls":["https://www.etsi.org/deliver/etsi_ts/138200_138299/138211/19.02.00_60/ts_138211v190200p.pdf"],"title":"5G NR Numerology：子載波間距與時槽時間","titleEn":"5G NR numerology: subcarrier spacing and slot duration","why":"用兩課的可觀察驗收條件比較模型邊界：交付物能重現 4560 microsecond/frame 與 4320 microsecond/frame，保留失敗情境且每個通過判定有明確門檻；需分開列出模型未涵蓋的實際系統驗證。","whyEn":"Compare model boundaries using observable acceptance criteria: The artifacts must reproduce 4560 microsecond/frame and 4320 microsecond/frame, preserve failing scenarios and attach a threshold to each pass decision; list actual-system validation outside this model separately.","difference":"能推導並解釋500 microsecond與125 microsecond，建立nr_slots.csv、時間格線、端到端延遲分解，並完成以下驗收：250 microsecond的時槽預算只由mu=3滿足；仍須單獨驗處理、排隊及重傳。","differenceEn":"Derive and explain 500 microsecond and 125 microsecond; create nr_slots.csv, timing grid and end-to-end delay decomposition; apply this acceptance decision: Only mu=3 fits a250 microsecond slot budget; processing, queueing and retries require separate verification.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["從原理 TDMA以互不重疊的時槽分配共用媒介；資料時間須扣保護時間，時槽數與語音淨位元率不可直接等同。 展開基準式 8*(600-30)；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：列8個槽的起訖與資料區，總框長4800 microsecond不變；確認無資料跨越保護邊界。 將兩條推導一起存入 tdma_slots.csv、到達偏移表、保護時間驗收。","從原理 正常CP之NR時槽時間依2^mu縮放；提高子載波間距縮短時槽，但不單獨保證端到端低延遲。 展開基準式 1000/2**1；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：每1 ms時間窗分別應放2與8個時槽；計數與時間乘積必須回到1000 microsecond。 將兩條推導一起存入 nr_slots.csv、時間格線、端到端延遲分解。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Starting from TDMA divides a shared medium into nonoverlapping slots; guard time reduces data time and slot count is not a voice payload rate., expand baseline expression 8*(600-30); record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: List start/end/data intervals for eight slots; total frame duration remains4800 microseconds and no data crosses a guard boundary. Save both derivations with tdma_slots.csv, arrival offsets and guard-time acceptance.","Starting from For normal-CP NR, slot duration scales with2^mu; larger subcarrier spacing shortens slots but does not alone guarantee low end-to-end latency., expand baseline expression 1000/2**1; record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: A1 ms window contains2 or8 slots; slot count times duration must recover1000 microseconds. Save both derivations with nr_slots.csv, timing grid and end-to-end delay decomposition.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v28-case-b12237ac3fc60f0b","url":"https://www.etsi.org/deliver/etsi_ts/145000_145099/145002/15.02.00_60/ts_145002v150200p.pdf","title":"ETSI TS 145 002 V15.2.0: GSM/EDGE Multiplexing and multiple access","titleEn":"ETSI TS 145 002 V15.2.0: GSM/EDGE Multiplexing and multiple access","publisher":"ETSI / 3GPP","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v28-case-0e90e3978e42dfde","url":"https://www.etsi.org/deliver/etsi_ts/138200_138299/138211/19.02.00_60/ts_138211v190200p.pdf","title":"ETSI TS 138 211 V19.2.0: NR physical channels and modulation","titleEn":"ETSI TS 138 211 V19.2.0: NR physical channels and modulation","publisher":"ETSI / 3GPP","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
